import json
d=json.load(open('materials.json'))
out=[]
def walk(o):
    if isinstance(o,dict):
        if o.get('type')=='text' and 'text' in o:
            out.append(o['text'])
        elif o.get('type')=='heading' and 'text' in o:
            out.append('\n## '+o['text'])
        elif o.get('type')=='paragraph':
            out.append('\n')
            for c in o.get('inlineContent',[]): walk(c)
            out.append('\n')
        elif o.get('type')=='listItem':
            out.append('\n- ')
            for c in o.get('content',[]): walk(c)
        elif o.get('type')=='reference' and 'title' in o:
            out.append(o['title'])
        else:
            for k,v in o.items():
                if k in ('references','metadata','seeAlsoSections','hierarchy','variants','identifier'): continue
                walk(v)
    elif isinstance(o,list):
        for i in o: walk(i)
walk(d)
open('materials.txt','w').write(''.join(out))
print(len(''.join(out)))
